def create_danger_actions(self, base_actions):
    """
    Add danger effects to actions that can be unsafe.
    """
    # ===== DOMAIN-SPECIFIC DANGER EFFECTS (CHANGE FOR NEW DOMAINS) =====
    dangerous_actions = {
        "transmit_data": And([
            Not(self.robot_in_active_mode),  # Not in active working mode
            self.robot_has_data,  # Has data to transmit
            self.control_system_operational  # Control system is operational
        ]),  # Transmitting data while in standby mode is dangerous
    }

    # ===== INFRASTRUCTURE (KEEP THIS LINE) =====
    return self.apply_danger_effects(base_actions, dangerous_actions)
